		cfg, f := ParseConfig([]byte(src))
		if f == nil || f.Code != "invalid_config" {
			t.Fatalf("upstream %q: got %+v, want invalid_config", up, f)
		}
		if cfg != nil {
			t.Fatalf("upstream %q: a rejected config must not be returned", up)
		}
	}
}

